<script setup lang="ts">
import {onMounted,watch,ref,onBeforeUnmount} from 'vue';import {Chart,registerables} from 'chart.js';Chart.register(...registerables);const props=defineProps<{labels:string[];values:number[];second?:number[]}>();const canvas=ref<HTMLCanvasElement>();let chart:Chart|undefined;function render(){chart?.destroy();if(canvas.value)chart=new Chart(canvas.value,{type:'bar',data:{labels:props.labels,datasets:[{label:'Estimated need / reports',data:props.values,backgroundColor:'#07878b',borderRadius:5},...(props.second?[{label:'Confirmed delivered',data:props.second,backgroundColor:'#82d8cb',borderRadius:5}]:[])]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:!!props.second,position:'bottom'}},scales:{y:{beginAtZero:true,grid:{color:'#eef2f5'}},x:{grid:{display:false}}}}})}onMounted(render);watch(()=>[props.values,props.labels,props.second],render,{deep:true});onBeforeUnmount(()=>chart?.destroy());
</script><template><div class="chart"><canvas ref="canvas" aria-label="Response analytics chart" role="img"></canvas></div></template>
